pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }
    function testFuzz_property(address from, address[] memory _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        vm.assume(_decimals <= 77);
        uint baseMul = 10 ** _decimals;
        vm.assume(v == 0 || baseMul <= type(uint).max / v);

        LoggingHelper helper = new LoggingHelper();
        vm.prank(from);
        bool refSuccess;
        try c.transfer(from, address(helper), _tos, v, _decimals) returns (bool ok) {
            refSuccess = ok;
        } catch {
            refSuccess = false;
        }
        if (refSuccess) {
            uint expectedValue = v * (10 ** _decimals);
            assertTrue(helper.lastValue() == expectedValue);
        }
    }
}

contract LoggingHelper {
    uint public lastValue;
    function transferFrom(address, address, uint value) external returns (bool) {
        lastValue = value;
        return true;
    }
}
